import {createClient} from 'https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2.99.1/+esm';
const db=createClient('https://mhebynaprmhxfbcsiqgf.supabase.co','sb_publishable_I4ffulPriroIpZgEDRO4_A_gh_4v2Vj');
const $=s=>document.querySelector(s);let feedMode='for_you';let user,tab='home',cursor=null,chat=null,poll=null,generation=0;
const node=(tag,text,cls)=>{const n=document.createElement(tag);if(text!=null)n.textContent=text;if(cls)n.className=cls;return n};
const status=t=>$('#status').textContent=t||'';
async function rpc(name,args={}){const r=await db.rpc('pulse_'+name,args);if(r.error)throw r.error;return r.data;}
async function signed(path,bucket='pulse-social'){const r=await db.storage.from(bucket).createSignedUrl(path,300);if(r.error)throw r.error;return r.data.signedUrl;}
function empty(text){$('#content').append(node('div',text,'empty'));}
async function session(){const r=await db.auth.getUser();user=r.data.user;$('#login').hidden=!!user;$('#app').hidden=!user;$('#nav').hidden=!user;$('#signout').hidden=!user;if(user){await rpc('account_status').then(r=>{if(!r.active)throw Error('This account is restricted. Please open Pulse to review its status.');});await show('home');}else{$('#heading').textContent='pulse';}}
$('#auth').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;status('Signing in…');try{const r=await db.auth.signInWithPassword({email:$('#email').value.trim(),password:$('#password').value});if(r.error)throw r.error;$('#password').value='';await session();status('');}catch(e){status(e.message);}finally{b.disabled=false;}};
$('#signout').onclick=async()=>{await db.auth.signOut({scope:'local'});clearInterval(poll);generation++;$('#content').replaceChildren();await session();};
$('#nav').onclick=e=>{const b=e.target.closest('button[data-tab]');if(b)show(b.dataset.tab)};$('#refresh').onclick=()=>show(tab);$('#mail-shortcut').onclick=()=>show('mail');$('#feedtabs').onclick=e=>{const b=e.target.closest('button[data-mode]');if(!b)return;feedMode=b.dataset.mode;document.querySelectorAll('#feedtabs button').forEach(x=>x.classList.toggle('active',x===b));show('home');};$('#more').onclick=()=>feed(true);
async function show(next){tab=next;cursor=null;chat=null;generation++;clearInterval(poll);$('#content').replaceChildren();$('#more').hidden=true;status('');$('#heading').textContent={home:'pulse',reels:'Reels',chats:'Chats',groups:'Groups',create:'Create post',mail:'Pulse mail',profile:'Profile'}[tab];$('#feedtabs').hidden=tab!=='home';$('#subtitle').textContent={home:'Discover posts from Pulse',reels:'Videos from your community',chats:'Your existing conversations',mail:'Public reward codes and announcements',profile:'Your Pulse profile',groups:'Your group conversations',create:'Create something worth sharing'}[tab];document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));try{if(tab==='home'||tab==='reels')await feed();else if(tab==='chats'||tab==='groups')await chats();else if(tab==='create')await createPost();else if(tab==='mail')await mail();else await profile();await badge();}catch(e){status(e.message||'Could not load Pulse. Please retry.');}}
async function feed(more=false){const ticket=generation;$('#more').disabled=true;try{const rows=await rpc('social_feed',{p_mode:tab==='home'&&feedMode==='following'?'following':'discovery',p_kind:tab==='reels'?'reel':'all',p_author:null,p_before:cursor?.created_at??null,p_cursor:cursor?.id??null,p_limit:12});if(ticket!==generation)return;if(!more&&rows.length===0)empty('Your feed is quiet right now. Come back soon.');for(const p of rows){const a=node('article');const head=node('div',null,'posthead'),portrait=node('img'),identity=node('div');portrait.className='portrait';portrait.alt='';portrait.src='assets/pulse.png';if(p.author?.avatar_path)signed(p.author.avatar_path,'pulse-avatars').then(url=>{if(portrait.isConnected)portrait.src=url}).catch(()=>{});identity.append(node('h3',(p.author?.display_name||'Pulse creator')+(p.author?.verified?' ✓':'')),node('time','@'+(p.author?.username||'creator')+' · '+new Date(p.created_at).toLocaleDateString()));head.append(portrait,identity);a.append(head,node('p',p.body||''));for(const m of p.media||[]){const media=node(m.kind==='video'?'video':'img');if(m.kind==='video'){media.controls=true;media.preload='none';media.playsInline=true;}else{media.alt=p.body||'Pulse post';media.loading='lazy';}a.append(media);signed(m.path).then(url=>{if(a.isConnected)media.src=url}).catch(()=>{media.replaceWith(node('p','This media is unavailable.'))});}const actions=node('div',null,'postactions');for(const [action,label,active]of [['like','♡ '+p.likes,p.liked],['save','▱ Save',p.saved]]){let enabled=!!active;const b=node('button',enabled?(action==='like'?'♥ '+p.likes:'▣ Saved'):label);b.onclick=async()=>{b.disabled=true;try{await rpc('social_action',{p_id:p.id,p_action:action,p_enabled:!enabled});enabled=!enabled;b.textContent=action==='like'?(enabled?'♥ ':'♡ ')+(Number(p.likes||0)+(enabled?1:0)-(p.liked?1:0)):(enabled?'▣ Saved':'▱ Save');}catch(e){status(e.message)}finally{b.disabled=false}};actions.append(b);}actions.append(node('span',p.comments+' comments'));a.append(actions);$('#content').append(a);}cursor=rows.at(-1)||cursor;$('#more').hidden=rows.length<12;}finally{$('#more').disabled=false;}}
async function chats(){const r=await db.from('pulse_chats').select('id,name,kind').order('created_at',{ascending:false}).limit(50);if(r.error)throw r.error;if(tab==='groups')r.data=r.data.filter(c=>c.kind==='group');if(!r.data.length){empty('No conversations yet. Start one in Pulse.');return;}const wrap=node('div',null,'chat'),list=node('div',null,'chatlist'),panel=node('div');wrap.append(list,panel);$('#content').append(wrap);for(const c of r.data){const b=node('button',c.name);b.onclick=()=>openChat(c,panel);list.append(b);}await openChat(r.data[0],panel);}
async function openChat(c,panel){clearInterval(poll);chat=c.id;panel.replaceChildren();panel.append(node('h3',c.name));const messages=node('div',null,'messages'),form=node('form'),input=node('input'),send=node('button','Send','primary');input.placeholder='Write a message…';input.maxLength=8000;input.required=true;send.type='submit';form.append(input,send);panel.append(messages,form);const load=async()=>{const id=chat;const r=await db.from('pulse_messages').select('id,body,sender_id,created_at,deleted_at').eq('chat_id',id).order('created_at',{ascending:false}).limit(100);if(chat!==id||!messages.isConnected)return;if(r.error){status(r.error.message);return;}messages.replaceChildren();for(const m of r.data.reverse())messages.append(node('div',m.deleted_at?'Message deleted':m.body,'bubble'+(m.sender_id===user.id?' mine':'')));messages.scrollTop=messages.scrollHeight;};form.onsubmit=async e=>{e.preventDefault();const text=input.value.trim();if(!text)return;send.disabled=true;try{await rpc('send_message',{p_id:crypto.randomUUID(),p_chat:c.id,p_body:text,p_reply:null,p_attachment:null});input.value='';await load();}catch(e){status(e.message)}finally{send.disabled=false}};await load();poll=setInterval(load,5000);}
async function mail(){const data=await rpc('reward_mail');if(!data.items.length)empty('You’re all caught up. New public codes will appear here.');for(const r of data.items){const a=node('article');a.append(node('h3',`${r.amount} ${r.kind}`),node('p',r.code),node('time','Expires '+new Date(r.expires_at).toLocaleString()));const b=node('button','Redeem code');b.onclick=async()=>{b.disabled=true;try{const result=await rpc('claim_reward',{p_code:r.code});status(result.message);}catch(e){status(e.message)}finally{b.disabled=false}};a.append(b);$('#content').append(a);}if(data.items.length)await rpc('reward_mail',{p_seen:data.items.map(r=>r.id)});await badge();}
async function badge(){try{const r=await rpc('reward_mail');$('#badge').hidden=!r.unread;$('#badge').textContent=r.unread>99?'99+':r.unread;$('#mail-shortcut').replaceChildren(document.createTextNode('✉'));if(r.unread)$('#mail-shortcut').append(node('b',r.unread>99?'99+':r.unread));}catch(_){}}
async function profile(){const p=await rpc('social_profile',{p_user:user.id});const a=node('article');const portrait=node('img');portrait.className='profileportrait';portrait.alt='Profile picture';portrait.src='assets/pulse.png';if(p.avatar_path)signed(p.avatar_path,'pulse-avatars').then(url=>portrait.src=url).catch(()=>{});a.className='profilecard';a.append(portrait,node('h2',p.display_name),node('p','@'+p.username),node('p',p.bio||''),node('p',`${p.followers} followers · ${p.following} following · ${p.analytics?.likes??0} likes`));$('#content').append(a);}
try{await session()}catch(e){status(e.message)}

async function createPost(){const form=node('form',null,'create'),title=node('h2','Share a thought'),body=node('textarea'),audience=node('select'),submit=node('button','Publish','primary');body.placeholder='Share a thought… Add #hashtags';body.maxLength=4000;body.required=true;for(const [value,label]of [['public','Everyone on Pulse'],['followers','Followers']]){const o=node('option',label);o.value=value;audience.append(o);}form.append(title,body,audience,node('p','Photo/video editing and uploads are available in the native app.'),submit);form.onsubmit=async e=>{e.preventDefault();submit.disabled=true;try{await rpc('social_write_options',{p_id:crypto.randomUUID(),p_kind:'post',p_body:body.value,p_media:[],p_audience:audience.value,p_draft:false,p_allow_download:true});await show('home');status('Post published.');}catch(e){status(e.message);}finally{submit.disabled=false}};$('#content').append(form);}
